```sql
WITH MostInfluentialUser AS (
    SELECT Id FROM users ORDER BY Reputation DESC LIMIT 1
),
PostsByMostInfluentialUser AS (
    SELECT * FROM posts WHERE OwnerUserId = (SELECT Id FROM MostInfluentialUser)
),
PostsAbove50 AS (
    SELECT COUNT(*) AS CountAbove50 FROM PostsByMostInfluentialUser WHERE Score > 50
),
TotalPosts AS (
    SELECT COUNT(*) AS TotalCount FROM PostsByMostInfluentialUser
)
SELECT CAST(PostsAbove50.CountAbove50 AS REAL) * 100 / TotalPosts.TotalCount AS Percentage
FROM PostsAbove50, TotalPosts;
```

