```sql
SELECT 
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'SME' AND Date BETWEEN '201301' AND '201312'
    )) - 
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'LAM' AND Date BETWEEN '201301' AND '201312'
    )) AS SME_LAM_diff,

    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'LAM' AND Date BETWEEN '201301' AND '201312'
    )) - 
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'KAM' AND Date BETWEEN '201301' AND '201312'
    )) AS LAM_KAM_diff,

    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'KAM' AND Date BETWEEN '201301' AND '201312'
    )) - 
    (SELECT AVG(Consumption) FROM yearmonth WHERE CustomerID IN (
        SELECT CustomerID FROM customers WHERE Segment = 'SME' AND Date BETWEEN '201301' AND '201312'
    )) AS KAM_SME_diff;
```

